import { useState, useEffect } from 'react';
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from '@/components/ui/dialog';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Textarea } from '@/components/ui/textarea';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select';
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from '@/components/ui/table';
import { Tabs, TabsContent, TabsList, TabsTrigger } from '@/components/ui/tabs';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card';
import { Badge } from '@/components/ui/badge';
import { useToast } from '@/hooks/use-toast';
import { 
  getInitiatives, 
  getAwardPoints, 
  getDepartments,
  addInitiative,
  updateInitiative,
  deleteInitiative,
  addAwardPoint,
  updateAwardPoint,
  deleteAwardPoint,
  addDepartment,
  updateDepartment,
  deleteDepartment,
  initializeDatabase
} from '../lib/database';
import { formatCurrency, parseCurrency } from '../lib/currency';
import { 
  Plus, 
  Edit, 
  Trash2, 
  Search, 
  Filter,
  Download,
  Upload,
  RefreshCw,
  Building,
  Target,
  Users
} from 'lucide-react';

function EnhancedDataManagement({ open, onOpenChange, onDataUpdate }) {
  const { toast } = useToast();
  const [loading, setLoading] = useState(false);
  const [activeTab, setActiveTab] = useState('initiatives');
  
  // Data states
  const [initiatives, setInitiatives] = useState([]);
  const [awardPoints, setAwardPoints] = useState([]);
  const [departments, setDepartments] = useState([]);
  
  // Dialog states
  const [editDialog, setEditDialog] = useState({ open: false, type: '', data: null });
  const [deleteDialog, setDeleteDialog] = useState({ open: false, type: '', id: null });
  
  // Search and filter states
  const [searchTerm, setSearchTerm] = useState('');
  const [statusFilter, setStatusFilter] = useState('all');
  const [departmentFilter, setDepartmentFilter] = useState('all');

  // Form data for editing
  const [formData, setFormData] = useState({});

  useEffect(() => {
    if (open) {
      loadAllData();
    }
  }, [open]);

  const loadAllData = async () => {
    setLoading(true);
    try {
      await initializeDatabase();
      const [initiativesData, awardPointsData, departmentsData] = await Promise.all([
        getInitiatives(),
        getAwardPoints(),
        getDepartments()
      ]);
      
      setInitiatives(initiativesData);
      setAwardPoints(awardPointsData);
      setDepartments(departmentsData);
    } catch (error) {
      console.error('Error loading data:', error);
      toast({
        title: "خطأ",
        description: "حدث خطأ في تحميل البيانات",
        variant: "destructive",
      });
    } finally {
      setLoading(false);
    }
  };

  const handleEdit = (type, item) => {
    setFormData(item);
    setEditDialog({ open: true, type, data: item });
  };

  const handleDelete = (type, id) => {
    setDeleteDialog({ open: true, type, id });
  };

  const handleAdd = (type) => {
    const defaultData = {
      initiatives: {
        name: '',
        department: '',
        status: 'لم تبدأ',
        completion_percentage: 0,
        planned_budget: 0,
        used_budget: 0,
        responsible_person: '',
        priority: 'متوسطة',
        description: ''
      },
      awardPoints: {
        point_type: 'نقطة تحسين',
        standard: '',
        standard_classification: '',
        department: '',
        description: '',
        status: 'لم تبدأ',
        responsible_person: ''
      },
      departments: {
        name: '',
        active: true
      }
    };
    
    setFormData(defaultData[type]);
    setEditDialog({ open: true, type, data: null });
  };

  const handleSave = async () => {
    setLoading(true);
    try {
      const { type, data } = editDialog;
      
      if (data) {
        // Update existing
        if (type === 'initiatives') {
          await updateInitiative(data.id, formData);
        } else if (type === 'awardPoints') {
          await updateAwardPoint(data.id, formData);
        } else if (type === 'departments') {
          await updateDepartment(data.id, formData);
        }
        toast({
          title: "تم التحديث",
          description: "تم تحديث البيانات بنجاح",
        });
      } else {
        // Add new
        if (type === 'initiatives') {
          await addInitiative(formData);
        } else if (type === 'awardPoints') {
          await addAwardPoint(formData);
        } else if (type === 'departments') {
          await addDepartment(formData);
        }
        toast({
          title: "تم الإضافة",
          description: "تم إضافة البيانات بنجاح",
        });
      }
      
      setEditDialog({ open: false, type: '', data: null });
      await loadAllData();
      onDataUpdate?.();
    } catch (error) {
      console.error('Error saving data:', error);
      toast({
        title: "خطأ",
        description: "حدث خطأ في حفظ البيانات",
        variant: "destructive",
      });
    } finally {
      setLoading(false);
    }
  };

  const handleDeleteConfirm = async () => {
    setLoading(true);
    try {
      const { type, id } = deleteDialog;
      
      if (type === 'initiatives') {
        await deleteInitiative(id);
      } else if (type === 'awardPoints') {
        await deleteAwardPoint(id);
      } else if (type === 'departments') {
        await deleteDepartment(id);
      }
      
      toast({
        title: "تم الحذف",
        description: "تم حذف البيانات بنجاح",
      });
      
      setDeleteDialog({ open: false, type: '', id: null });
      await loadAllData();
      onDataUpdate?.();
    } catch (error) {
      console.error('Error deleting data:', error);
      toast({
        title: "خطأ",
        description: "حدث خطأ في حذف البيانات",
        variant: "destructive",
      });
    } finally {
      setLoading(false);
    }
  };

  const getStatusBadge = (status) => {
    const statusColors = {
      'لم تبدأ': 'bg-gray-500',
      'قيد التنفيذ': 'bg-blue-500',
      'مكتملة': 'bg-green-500',
      'متأخرة': 'bg-red-500'
    };
    
    return (
      <Badge className={`text-white ${statusColors[status] || 'bg-gray-500'}`}>
        {status}
      </Badge>
    );
  };

  const getPriorityBadge = (priority) => {
    const priorityColors = {
      'عالية': 'bg-red-500',
      'متوسطة': 'bg-yellow-500',
      'منخفضة': 'bg-green-500'
    };
    
    return (
      <Badge className={`text-white ${priorityColors[priority] || 'bg-gray-500'}`}>
        {priority}
      </Badge>
    );
  };

  const filteredInitiatives = initiatives.filter(item => {
    const matchesSearch = item.name?.toLowerCase().includes(searchTerm.toLowerCase()) ||
                         item.responsible_person?.toLowerCase().includes(searchTerm.toLowerCase());
    const matchesStatus = statusFilter === 'all' || item.status === statusFilter;
    const matchesDepartment = departmentFilter === 'all' || item.department === departmentFilter;
    
    return matchesSearch && matchesStatus && matchesDepartment;
  });

  const filteredAwardPoints = awardPoints.filter(item => {
    const matchesSearch = item.description?.toLowerCase().includes(searchTerm.toLowerCase()) ||
                         item.standard?.toLowerCase().includes(searchTerm.toLowerCase());
    const matchesStatus = statusFilter === 'all' || item.status === statusFilter;
    const matchesDepartment = departmentFilter === 'all' || item.department === departmentFilter;
    
    return matchesSearch && matchesStatus && matchesDepartment;
  });

  return (
    <>
      <Dialog open={open} onOpenChange={onOpenChange}>
        <DialogContent className="max-w-7xl max-h-[90vh] overflow-y-auto" dir="rtl">
          <DialogHeader>
            <DialogTitle className="text-right flex items-center gap-2" style={{color: 'var(--brand-orange)'}}>
              <Building className="h-5 w-5" />
              إدارة البيانات الشاملة
            </DialogTitle>
            <DialogDescription className="text-right">
              إدارة جميع بيانات النظام من مكان واحد
            </DialogDescription>
          </DialogHeader>

          <div className="space-y-4">
            {/* Search and Filter Controls */}
            <div className="flex flex-col md:flex-row gap-4 p-4 bg-gray-50 rounded-lg">
              <div className="flex-1">
                <div className="relative">
                  <Search className="absolute right-3 top-1/2 transform -translate-y-1/2 text-gray-400 h-4 w-4" />
                  <Input
                    placeholder="البحث في البيانات..."
                    value={searchTerm}
                    onChange={(e) => setSearchTerm(e.target.value)}
                    className="pr-10 text-right"
                  />
                </div>
              </div>
              
              <Select value={statusFilter} onValueChange={setStatusFilter}>
                <SelectTrigger className="w-full md:w-48 text-right">
                  <SelectValue placeholder="تصفية حسب الحالة" />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="all">جميع الحالات</SelectItem>
                  <SelectItem value="لم تبدأ">لم تبدأ</SelectItem>
                  <SelectItem value="قيد التنفيذ">قيد التنفيذ</SelectItem>
                  <SelectItem value="مكتملة">مكتملة</SelectItem>
                  <SelectItem value="متأخرة">متأخرة</SelectItem>
                </SelectContent>
              </Select>

              <Select value={departmentFilter} onValueChange={setDepartmentFilter}>
                <SelectTrigger className="w-full md:w-48 text-right">
                  <SelectValue placeholder="تصفية حسب الإدارة" />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="all">جميع الإدارات</SelectItem>
                  {departments.map((dept) => (
                    <SelectItem key={dept.id} value={dept.name}>
                      {dept.name}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>

              <Button
                onClick={loadAllData}
                variant="outline"
                className="flex items-center gap-2"
                disabled={loading}
              >
                <RefreshCw className={`h-4 w-4 ${loading ? 'animate-spin' : ''}`} />
                تحديث
              </Button>
            </div>

            {/* Data Tabs */}
            <Tabs value={activeTab} onValueChange={setActiveTab} className="w-full">
              <TabsList className="grid w-full grid-cols-3">
                <TabsTrigger value="initiatives" className="flex items-center gap-2">
                  <Target className="h-4 w-4" />
                  المبادرات ({initiatives.length})
                </TabsTrigger>
                <TabsTrigger value="awardPoints" className="flex items-center gap-2">
                  <Target className="h-4 w-4" />
                  نقاط الجائزة ({awardPoints.length})
                </TabsTrigger>
                <TabsTrigger value="departments" className="flex items-center gap-2">
                  <Users className="h-4 w-4" />
                  الإدارات ({departments.length})
                </TabsTrigger>
              </TabsList>

              {/* Initiatives Tab */}
              <TabsContent value="initiatives" className="space-y-4">
                <div className="flex justify-between items-center">
                  <h3 className="text-lg font-semibold">إدارة المبادرات</h3>
                  <Button
                    onClick={() => handleAdd('initiatives')}
                    className="flex items-center gap-2"
                    style={{backgroundColor: 'var(--brand-orange)'}}
                  >
                    <Plus className="h-4 w-4" />
                    إضافة مبادرة
                  </Button>
                </div>

                <div className="border rounded-lg overflow-hidden">
                  <Table>
                    <TableHeader>
                      <TableRow>
                        <TableHead className="text-right">اسم المبادرة</TableHead>
                        <TableHead className="text-right">الإدارة</TableHead>
                        <TableHead className="text-right">المسؤول</TableHead>
                        <TableHead className="text-right">الحالة</TableHead>
                        <TableHead className="text-right">الأولوية</TableHead>
                        <TableHead className="text-right">نسبة الإكمال</TableHead>
                        <TableHead className="text-right">الميزانية</TableHead>
                        <TableHead className="text-right">الإجراءات</TableHead>
                      </TableRow>
                    </TableHeader>
                    <TableBody>
                      {filteredInitiatives.map((initiative) => (
                        <TableRow key={initiative.id}>
                          <TableCell className="text-right font-medium">
                            {initiative.name}
                          </TableCell>
                          <TableCell className="text-right">{initiative.department}</TableCell>
                          <TableCell className="text-right">{initiative.responsible_person}</TableCell>
                          <TableCell className="text-right">
                            {getStatusBadge(initiative.status)}
                          </TableCell>
                          <TableCell className="text-right">
                            {getPriorityBadge(initiative.priority)}
                          </TableCell>
                          <TableCell className="text-right">
                            <div className="flex items-center gap-2">
                              <div className="w-16 bg-gray-200 rounded-full h-2">
                                <div
                                  className="bg-blue-600 h-2 rounded-full"
                                  style={{ width: `${initiative.completion_percentage}%` }}
                                ></div>
                              </div>
                              <span className="text-sm">{initiative.completion_percentage}%</span>
                            </div>
                          </TableCell>
                          <TableCell className="text-right">
                            <div className="text-sm">
                              <div>مخطط: {formatCurrency(initiative.planned_budget)}</div>
                              <div>مستخدم: {formatCurrency(initiative.used_budget)}</div>
                            </div>
                          </TableCell>
                          <TableCell className="text-right">
                            <div className="flex gap-2">
                              <Button
                                size="sm"
                                variant="outline"
                                onClick={() => handleEdit('initiatives', initiative)}
                              >
                                <Edit className="h-4 w-4" />
                              </Button>
                              <Button
                                size="sm"
                                variant="outline"
                                onClick={() => handleDelete('initiatives', initiative.id)}
                                className="text-red-600 hover:text-red-700"
                              >
                                <Trash2 className="h-4 w-4" />
                              </Button>
                            </div>
                          </TableCell>
                        </TableRow>
                      ))}
                    </TableBody>
                  </Table>
                </div>
              </TabsContent>

              {/* Award Points Tab */}
              <TabsContent value="awardPoints" className="space-y-4">
                <div className="flex justify-between items-center">
                  <h3 className="text-lg font-semibold">إدارة نقاط الجائزة</h3>
                  <Button
                    onClick={() => handleAdd('awardPoints')}
                    className="flex items-center gap-2"
                    style={{backgroundColor: 'var(--brand-orange)'}}
                  >
                    <Plus className="h-4 w-4" />
                    إضافة نقطة جائزة
                  </Button>
                </div>

                <div className="border rounded-lg overflow-hidden">
                  <Table>
                    <TableHeader>
                      <TableRow>
                        <TableHead className="text-right">نوع النقطة</TableHead>
                        <TableHead className="text-right">المعيار</TableHead>
                        <TableHead className="text-right">تصنيف المعيار</TableHead>
                        <TableHead className="text-right">الإدارة</TableHead>
                        <TableHead className="text-right">الحالة</TableHead>
                        <TableHead className="text-right">المسؤول</TableHead>
                        <TableHead className="text-right">الإجراءات</TableHead>
                      </TableRow>
                    </TableHeader>
                    <TableBody>
                      {filteredAwardPoints.map((point) => (
                        <TableRow key={point.id}>
                          <TableCell className="text-right">
                            <Badge variant={point.point_type === 'نقطة قوة' ? 'default' : 'secondary'}>
                              {point.point_type}
                            </Badge>
                          </TableCell>
                          <TableCell className="text-right">{point.standard}</TableCell>
                          <TableCell className="text-right">{point.standard_classification}</TableCell>
                          <TableCell className="text-right">{point.department}</TableCell>
                          <TableCell className="text-right">
                            {getStatusBadge(point.status)}
                          </TableCell>
                          <TableCell className="text-right">{point.responsible_person}</TableCell>
                          <TableCell className="text-right">
                            <div className="flex gap-2">
                              <Button
                                size="sm"
                                variant="outline"
                                onClick={() => handleEdit('awardPoints', point)}
                              >
                                <Edit className="h-4 w-4" />
                              </Button>
                              <Button
                                size="sm"
                                variant="outline"
                                onClick={() => handleDelete('awardPoints', point.id)}
                                className="text-red-600 hover:text-red-700"
                              >
                                <Trash2 className="h-4 w-4" />
                              </Button>
                            </div>
                          </TableCell>
                        </TableRow>
                      ))}
                    </TableBody>
                  </Table>
                </div>
              </TabsContent>

              {/* Departments Tab */}
              <TabsContent value="departments" className="space-y-4">
                <div className="flex justify-between items-center">
                  <h3 className="text-lg font-semibold">إدارة الأقسام</h3>
                  <Button
                    onClick={() => handleAdd('departments')}
                    className="flex items-center gap-2"
                    style={{backgroundColor: 'var(--brand-orange)'}}
                  >
                    <Plus className="h-4 w-4" />
                    إضافة إدارة
                  </Button>
                </div>

                <div className="border rounded-lg overflow-hidden">
                  <Table>
                    <TableHeader>
                      <TableRow>
                        <TableHead className="text-right">اسم الإدارة</TableHead>
                        <TableHead className="text-right">الحالة</TableHead>
                        <TableHead className="text-right">الإجراءات</TableHead>
                      </TableRow>
                    </TableHeader>
                    <TableBody>
                      {departments.map((dept) => (
                        <TableRow key={dept.id}>
                          <TableCell className="text-right font-medium">{dept.name}</TableCell>
                          <TableCell className="text-right">
                            <Badge variant={dept.active ? 'default' : 'secondary'}>
                              {dept.active ? 'نشط' : 'غير نشط'}
                            </Badge>
                          </TableCell>
                          <TableCell className="text-right">
                            <div className="flex gap-2">
                              <Button
                                size="sm"
                                variant="outline"
                                onClick={() => handleEdit('departments', dept)}
                              >
                                <Edit className="h-4 w-4" />
                              </Button>
                              <Button
                                size="sm"
                                variant="outline"
                                onClick={() => handleDelete('departments', dept.id)}
                                className="text-red-600 hover:text-red-700"
                              >
                                <Trash2 className="h-4 w-4" />
                              </Button>
                            </div>
                          </TableCell>
                        </TableRow>
                      ))}
                    </TableBody>
                  </Table>
                </div>
              </TabsContent>
            </Tabs>
          </div>

          <DialogFooter className="flex justify-start gap-2 pt-4">
            <Button variant="outline" onClick={() => onOpenChange(false)}>
              إغلاق
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>

      {/* Edit Dialog */}
      <Dialog open={editDialog.open} onOpenChange={(open) => setEditDialog(prev => ({ ...prev, open }))}>
        <DialogContent className="sm:max-w-[600px] max-h-[90vh] overflow-y-auto" dir="rtl">
          <DialogHeader>
            <DialogTitle className="text-right">
              {editDialog.data ? 'تعديل' : 'إضافة'} {
                editDialog.type === 'initiatives' ? 'مبادرة' :
                editDialog.type === 'awardPoints' ? 'نقطة جائزة' : 'إدارة'
              }
            </DialogTitle>
          </DialogHeader>

          <div className="space-y-4">
            {editDialog.type === 'initiatives' && (
              <>
                <div>
                  <Label className="text-right block mb-2">اسم المبادرة *</Label>
                  <Input
                    value={formData.name || ''}
                    onChange={(e) => setFormData(prev => ({ ...prev, name: e.target.value }))}
                    className="text-right"
                    placeholder="أدخل اسم المبادرة"
                  />
                </div>
                <div>
                  <Label className="text-right block mb-2">الإدارة *</Label>
                  <Select
                    value={formData.department || ''}
                    onValueChange={(value) => setFormData(prev => ({ ...prev, department: value }))}
                  >
                    <SelectTrigger className="text-right">
                      <SelectValue placeholder="اختر الإدارة" />
                    </SelectTrigger>
                    <SelectContent>
                      {departments.map((dept) => (
                        <SelectItem key={dept.id} value={dept.name}>
                          {dept.name}
                        </SelectItem>
                      ))}
                    </SelectContent>
                  </Select>
                </div>
                <div>
                  <Label className="text-right block mb-2">المسؤول *</Label>
                  <Input
                    value={formData.responsible_person || ''}
                    onChange={(e) => setFormData(prev => ({ ...prev, responsible_person: e.target.value }))}
                    className="text-right"
                    placeholder="أدخل اسم المسؤول"
                  />
                </div>
                <div>
                  <Label className="text-right block mb-2">الوصف</Label>
                  <Textarea
                    value={formData.description || ''}
                    onChange={(e) => setFormData(prev => ({ ...prev, description: e.target.value }))}
                    className="text-right"
                    placeholder="أدخل وصف المبادرة"
                  />
                </div>
              </>
            )}

            {editDialog.type === 'awardPoints' && (
              <>
                <div>
                  <Label className="text-right block mb-2">نوع النقطة *</Label>
                  <Select
                    value={formData.point_type || ''}
                    onValueChange={(value) => setFormData(prev => ({ ...prev, point_type: value }))}
                  >
                    <SelectTrigger className="text-right">
                      <SelectValue placeholder="اختر نوع النقطة" />
                    </SelectTrigger>
                    <SelectContent>
                      <SelectItem value="نقطة قوة">نقطة قوة</SelectItem>
                      <SelectItem value="نقطة تحسين">نقطة تحسين</SelectItem>
                    </SelectContent>
                  </Select>
                </div>
                <div>
                  <Label className="text-right block mb-2">المعيار *</Label>
                  <Input
                    value={formData.standard || ''}
                    onChange={(e) => setFormData(prev => ({ ...prev, standard: e.target.value }))}
                    className="text-right"
                    placeholder="أدخل المعيار"
                  />
                </div>
                <div>
                  <Label className="text-right block mb-2">تصنيف المعيار</Label>
                  <Input
                    value={formData.standard_classification || ''}
                    onChange={(e) => setFormData(prev => ({ ...prev, standard_classification: e.target.value }))}
                    className="text-right"
                    placeholder="أدخل تصنيف المعيار"
                  />
                </div>
                <div>
                  <Label className="text-right block mb-2">الإدارة *</Label>
                  <Select
                    value={formData.department || ''}
                    onValueChange={(value) => setFormData(prev => ({ ...prev, department: value }))}
                  >
                    <SelectTrigger className="text-right">
                      <SelectValue placeholder="اختر الإدارة" />
                    </SelectTrigger>
                    <SelectContent>
                      {departments.map((dept) => (
                        <SelectItem key={dept.id} value={dept.name}>
                          {dept.name}
                        </SelectItem>
                      ))}
                    </SelectContent>
                  </Select>
                </div>
                <div>
                  <Label className="text-right block mb-2">الوصف *</Label>
                  <Textarea
                    value={formData.description || ''}
                    onChange={(e) => setFormData(prev => ({ ...prev, description: e.target.value }))}
                    className="text-right"
                    placeholder="أدخل وصف النقطة"
                  />
                </div>
              </>
            )}

            {editDialog.type === 'departments' && (
              <>
                <div>
                  <Label className="text-right block mb-2">اسم الإدارة *</Label>
                  <Input
                    value={formData.name || ''}
                    onChange={(e) => setFormData(prev => ({ ...prev, name: e.target.value }))}
                    className="text-right"
                    placeholder="أدخل اسم الإدارة"
                  />
                </div>
                <div>
                  <Label className="text-right block mb-2">الحالة</Label>
                  <Select
                    value={formData.active ? 'true' : 'false'}
                    onValueChange={(value) => setFormData(prev => ({ ...prev, active: value === 'true' }))}
                  >
                    <SelectTrigger className="text-right">
                      <SelectValue />
                    </SelectTrigger>
                    <SelectContent>
                      <SelectItem value="true">نشط</SelectItem>
                      <SelectItem value="false">غير نشط</SelectItem>
                    </SelectContent>
                  </Select>
                </div>
              </>
            )}
          </div>

          <DialogFooter className="flex justify-start gap-2 pt-4">
            <Button
              variant="outline"
              onClick={() => setEditDialog({ open: false, type: '', data: null })}
            >
              إلغاء
            </Button>
            <Button
              onClick={handleSave}
              disabled={loading}
              style={{backgroundColor: 'var(--brand-orange)'}}
            >
              {loading ? 'جاري الحفظ...' : 'حفظ'}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>

      {/* Delete Confirmation Dialog */}
      <Dialog open={deleteDialog.open} onOpenChange={(open) => setDeleteDialog(prev => ({ ...prev, open }))}>
        <DialogContent className="sm:max-w-[400px]" dir="rtl">
          <DialogHeader>
            <DialogTitle className="text-right text-red-600">تأكيد الحذف</DialogTitle>
            <DialogDescription className="text-right">
              هل أنت متأكد من حذف هذا العنصر؟ لا يمكن التراجع عن هذا الإجراء.
            </DialogDescription>
          </DialogHeader>
          <DialogFooter className="flex justify-start gap-2">
            <Button
              variant="outline"
              onClick={() => setDeleteDialog({ open: false, type: '', id: null })}
            >
              إلغاء
            </Button>
            <Button
              onClick={handleDeleteConfirm}
              disabled={loading}
              className="bg-red-600 hover:bg-red-700 text-white"
            >
              {loading ? 'جاري الحذف...' : 'حذف'}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </>
  );
}

export default EnhancedDataManagement;
